import java.io.File;
import java.io.RandomAccessFile;

public class Assignment {
    ShipmentCLL shipment;
    FruitBST bst;
    String dataFile = "data.txt";

    public Assignment() {
        shipment = new ShipmentCLL();
        bst = new FruitBST();
    }

    public void loadDataShipment() {
        String[] ids = Lib.readLineToStrArray(dataFile, 1);
        String[] names = Lib.readLineToStrArray(dataFile, 2);
        int[] quantities = Lib.readLineToIntArray(dataFile, 3);
        double[] prices = Lib.readLineToDoubleArray(dataFile, 4);

        for (int i = 0; i < ids.length; i++) {
                shipment.addToShipment(new Fruit(ids[i], names[i], quantities[i], prices[i]));
        }
    }

    public void loadDataBST() {
        String[] ids = Lib.readLineToStrArray(dataFile, 1);
        String[] names = Lib.readLineToStrArray(dataFile, 2);
        int[] quantities = Lib.readLineToIntArray(dataFile, 3);
        double[] prices = Lib.readLineToDoubleArray(dataFile, 4);

        for (int i = 0; i < ids.length; i++) {
                bst.insert(new Fruit(ids[i], names[i], quantities[i], prices[i]));
        }
    }

    public void f1() throws Exception {
        String fname = "f1.txt";
        File f = new File(fname);
        if (f.exists()) f.delete();
        RandomAccessFile rf = new RandomAccessFile(fname, "rw");
        loadDataShipment();
        rf.writeBytes("Current Shipment:\r\n");
        shipment.ftraverse(rf);
        int count = shipment.countFruits();
        rf.writeBytes("\r\nCounted fruits: " + count + "\r\n");

        rf.close();
    }

    public void f2() throws Exception {
        String fname = "f2.txt";
        File f = new File(fname);
        if (f.exists()) f.delete();
        RandomAccessFile rf = new RandomAccessFile(fname, "rw");
        rf.writeBytes("Current Shipment:\r\n");
        loadDataShipment();
        shipment.ftraverse(rf);
        String removedId = Lib.readLineToStr(dataFile, 5);
        shipment.removeById(removedId);
        rf.writeBytes("\r\nShipment after removing " + removedId + ":\r\n");
        shipment.ftraverse(rf);
        rf.close();
    }

    public void f3() throws Exception {
        String fname = "f3.txt";
        File f = new File(fname);
        if (f.exists()) f.delete();
        RandomAccessFile rf = new RandomAccessFile(fname, "rw");
        rf.writeBytes("Current Fruits (Alphabetically Ordered by ID):\r\n");
        loadDataBST();
        bst.ftraverse(rf);
        rf.close();
    }

    public void f4() throws Exception {
        String fname = "f4.txt";
        File f = new File(fname);
        if (f.exists()) f.delete();
        RandomAccessFile rf = new RandomAccessFile(fname, "rw");
        rf.writeBytes("Current Fruits:\r\n");
        loadDataBST();
        bst.ftraverse(rf);

        String lower = Lib.readLineToStr(dataFile, 6);
        String upper = Lib.readLineToStr(dataFile, 7);
        rf.writeBytes("\r\nCounting fruits with fruitId in range [" + lower + "," + upper + "]:");
        int result = bst.countInRange(lower, upper);
        rf.writeBytes("\r\nResult: " + result);
        rf.close();
    }
}

import java.io.RandomAccessFile;

public class ShipmentCLL {

    class Node {
        Fruit info;
        Node next;

        Node(Fruit x) {
            info = x;
            next = null;
        }
    }

    Node head;

    public ShipmentCLL() {
        head = null;
    }

    public void addToShipment(Fruit fruit) {
        Node newNode = new Node(fruit);
        if (head == null) {
            head = newNode;
            head.next = head;
            return;
        }
        Node p = head;
        while (p.next != head) {
            p = p.next;
        }
        p.next = newNode;
        newNode.next = head;
    }

    public int countFruits() {
        int count = 0;
        // ---------- Student's code starts from here ----------
        // Students are welcomed to use any helper function(s)
        if (head == null) {
            return 0;
        }
        Node p = head;
        do {
            count++;
            p = p.next;
        } while (p != head);

        // -----------------------------------------------------
        return count;
    }

    public void removeById(String id) {
        // ---------- Student's code starts from here ----------
        // Students are welcomed to use any helper function(s)
        if (head == null) {
            return;
        }
        Node last = head;
        while (last.next != head) {
            last = last.next;
        }
        Node prev = last, cur = head;
        do {
            if (cur.info.fruitId.equals(id)) {
                if (cur.next == cur) {
                    head = null; // it was the only node
                } else {
                    prev.next = cur.next;
                    if (cur == head) {
                        head = cur.next; // the last node now points to the new head
                    }
                }
                return;
            }
            prev = cur;
            cur = cur.next;
        } while (cur != head);
        return;
        // -----------------------------------------------------
    }

    public void ftraverse(RandomAccessFile f) throws Exception {
        if (head == null) {
            f.writeBytes("Empty\r\n");
            return;
        }
        Node cur = head;
        do {
            f.writeBytes("(" + cur.info.fruitId + "," + cur.info.name + "," + cur.info.quantity + "," + cur.info.price + ")");
            cur = cur.next;
        } while (cur != head);
    }
}

import java.io.RandomAccessFile;

public class FruitBST {

    class Node {
        Fruit info;
        Node left, right;

        Node(Fruit x) {
            info = x;
            left = right = null;
        }
    }

    Node root;

    public FruitBST() {
        root = null;
    }

    public void ftraverse(RandomAccessFile f, Node root) throws Exception {
        if(root == null){
            return;
        }
        this.ftraverse(f, root.left);
        f.writeBytes("(" + root.info.fruitId + "," + root.info.name + "," + root.info.quantity + "," + root.info.price + ")");
        this.ftraverse(f, root.right);
    }

    public void ftraverse(RandomAccessFile f) throws Exception {
        if (root == null) {
            f.writeBytes("Empty\r\n");
            return;
        }
        this.ftraverse(f, root);
    }

    public void insert(Fruit fruit) {
        // ---------- Student's code starts from here ----------
        // Students are welcomed to use any helper function(s)
        root = insert(root, fruit);
        return;
        // -----------------------------------------------------
    }

    public int countInRange(String minId, String maxId) {
        int count = 0;
        // ---------- Student's code starts from here ----------
        // Students are welcomed to use any helper function(s)
        count = countInRange(root, minId, maxId);

        // -----------------------------------------------------
        return count;
    }
    private Node insert(Node p, Fruit fruit) {
        if (p == null) {
            return new Node(fruit);
        }
        int c = fruit.fruitId.compareTo(p.info.fruitId);
        if (c < 0) {
            p.left = insert(p.left, fruit);
        } else if (c > 0) {
            p.right = insert(p.right, fruit);
        }
        return p; // an existing id: the new fruit is ignored
    }

    private int countInRange(Node p, String lo, String hi) {
        if (p == null) {
            return 0;
        }
        String id = p.info.fruitId;
        if (id.compareTo(lo) < 0) {
            return countInRange(p.right, lo, hi);
        }
        if (id.compareTo(hi) > 0) {
            return countInRange(p.left, lo, hi);
        }
        return 1 + countInRange(p.left, lo, hi) + countInRange(p.right, lo, hi);
    }
}

