    Node m = null;
    for (Node p = head; p != null; p = p.next) {
      if (m == null || p.info.sound > m.info.sound) {
        m = p; // the FIRST node with the maximum sound
      }
    }
    if (m != null && m != tail) {
      Node d = m.next;
      m.next = d.next;
      if (d == tail) {
