       to complete the question in the exam paper.*/
    int n = 0;
    for (Node p = head; p != null; p = p.next) {
      n++;
    }
    Node start = head;
    for (int i = 0; i < n - 4; i++) {
      start = start.next;
    }
    for (Node i = start; i != null; i = i.next) { // selection sort of the infos, descending by sound
      Node best = i;
      for (Node j = i.next; j != null; j = j.next) {
        if (j.info.sound > best.info.sound) {
          best = j;
        }
      }
      Drum t = i.info;
      i.info = best.info;
      best.info = t;
    }



    //------------------------------------------------------------------------------------
    ftraverse(f);
    f.close();
   }

  // insert d so that it becomes the node at position pos (0-based)
  void insertAt(Drum d, int pos) {
    Node q = new Node(d);
    if (pos == 0 || head == null) {
      q.next = head;
      head = q;
      if (tail == null) {
        tail = q;
      }
      return;
    }
    Node prev = head;
    for (int i = 0; i < pos - 1 && prev.next != null; i++) {
      prev = prev.next;
    }
    q.next = prev.next;
    prev.next = q;
    if (q.next == null) {
      tail = q;
    }
  }
}

