  // pre-order, only the tigers with rate < 6
  void preOrder2(Node p, RandomAccessFile f) throws Exception {
    if (p == null) {
      return;
    }
    if (p.info.rate < 6) {
      fvisit(p, f);
    }
    preOrder2(p.left, f);
    preOrder2(p.right, f);
  }

  // the k-th node (k = 1, 2, ...) in pre-order, or null
  Node kthPre(int k) {
    java.util.ArrayDeque<Node> st = new java.util.ArrayDeque<Node>();
    int count = 0;
    if (root != null) {
      st.push(root);
    }
    while (!st.isEmpty()) {
      Node p = st.pop();
      if (++count == k) {
        return p;
      }
      if (p.right != null) {
        st.push(p.right);
      }
      if (p.left != null) {
        st.push(p.left);
      }
    }
    return null;
  }

  Node parentOf(Node x) {
    Node f = null, p = root;
    while (p != null && p != x) {
      f = p;
      p = x.info.sound < p.info.sound ? p.left : p.right;
    }
    return f;
  }

  void deleteByCopying(Node p) {
    if (p == null) {
      return;
    }
    if (p.left != null && p.right != null) {
      Node f = p, q = p.left;
      while (q.right != null) {
        f = q;
        q = q.right;
      }
      p.info = q.info;
      if (f == p) {
        f.left = q.left;
      } else {
        f.right = q.left;
      }
      return;
    }
    Node child = p.left != null ? p.left : p.right;
    Node f = parentOf(p);
    if (f == null) {
      root = child;
    } else if (f.left == p) {
      f.left = child;
    } else {
      f.right = child;
    }
  }

  void rotateLeft(Node p) {
    if (p == null || p.right == null) {
      return;
    }
    Node f = parentOf(p);
    Node q = p.right;
    p.right = q.left;
    q.left = p;
    if (f == null) {
      root = q;
    } else if (f.left == p) {
      f.left = q;
    } else {
      f.right = q;
    }
  }
}

